type StakerVersion is uint256;
type MilestoneId is uint96;
enum MilestoneStatus {
    Pending,
    Failed,
    Succeeded
}
struct LockParams {
    uint256 startTime;
    uint256 cliffDuration;
    uint256 lockDuration;
}
struct Lock {
    uint256 startTime;
    uint256 cliff;
    uint256 endTime;
    uint256 allocation;
}
